const scopedDefaults={planMode:'scenes',idea:'',instruction:'',moment:'',perspective:'omniscient',pov:'',factIds:[],writer:'',extract:'',reviewPrompt:'',projectName:'',sceneTitle:'',sceneCount:1,scenePlans:'',plannerPrompt:''};
