function chapterDisplay(raw){const text=String(raw??''),m=/^(?:﻿)?#{1,6}[ \t]+(第[零〇一二三四五六七八九十百千万两0-9０-９]+[章回节][^\r\n]*)(?:\r?\n|$)/u.exec(text);return m?{title:m[1],body:text.slice(m[0].length)}:null}
